    if(action==='media-delete'){const media=state.media.find(m=>String(m.id)===b.dataset.id);if(media&&JSON.stringify(state.site).includes(media.url))throw new Error('Изображение используется в текущем черновике сайта. Сначала замените его и сохраните сайт.');if(await confirmAction('Архивировать изображение?','Используемые изображения нельзя архивировать. Сначала замените их в товарах или секциях и сохраните сайт.')){await request('/api/admin/media/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});tell('Изображение перемещено в архив.');render('media');}}
    if(action==='person-new'){state.site.content.founders.push({id:'founder-'+Date.now(),name:'НОВЫЙ ОСНОВАТЕЛЬ',image:'',bio:''});dirty();render('people');}
    if(action==='person-delete'&&await confirmAction('Убрать карточку основателя?','Изменение затронет только страницу «Про нас». Фотография останется в медиатеке.')){state.site.content.founders.splice(i,1);dirty();render('people');}
    if(action==='section-move'){const list=state.site.content.homepageSections;const j=i+Number(b.dataset.dir);if(j>=0&&j<list.length){[list[i],list[j]]=[list[j],list[i]];dirty();render('sections');}}
    if(action==='custom-new'){const id='custom-'+Date.now();state.site.content.customSections.push({id,title:{ru:'Новая секция',uk:'Нова секція',en:'New section',fr:'Nouvelle section'},body:{ru:'',uk:'',en:'',fr:''},image:'',buttonLabel:{ru:'',uk:'',en:'',fr:''},buttonHref:'#/shop'});state.site.content.homepageSections.push(id);dirty();showSection(id);}
    if(action==='custom-edit')showSection(b.dataset.id);
    if(action==='custom-done'){$('#editorDialog').close();render('sections');}
    if(action==='custom-delete'&&await confirmAction('Удалить секцию?','Содержимое блока будет удалено из черновика сайта.')){const c=state.site.content;c.customSections=c.customSections.filter(s=>s.id!==b.dataset.id);c.homepageSections=c.homepageSections.filter(s=>s!==b.dataset.id);c.hiddenSections=c.hiddenSections.filter(s=>s!==b.dataset.id);dirty();render('sections');}
    if(action==='page-new'){state.site.content.pages.push({slug:'page-'+Date.now(),title:{ru:'Новая страница',uk:'Нова сторінка',en:'New page',fr:'Nouvelle page'},body:{ru:'',uk:'',en:'',fr:''}});dirty();showPage(state.site.content.pages.length-1);}
    if(action==='page-edit')showPage(i);
    if(action==='page-done'){const pages=state.site.content.pages;const page=pages[+$('#editorDialog').dataset.page];if(!/^[a-z0-9][a-z0-9-]{0,79}$/i.test(page.slug))throw new Error('Адрес страницы: латинские буквы, цифры и дефисы.');if(pages.some(p=>p!==page&&p.slug===page.slug))throw new Error('Страница с таким адресом уже существует.');$('#editorDialog').close();render('sections');}
    if(action==='page-delete'&&await confirmAction('Удалить страницу?','Удалите также ссылки на эту страницу из меню, если они были добавлены.')){state.site.content.pages.splice(i,1);dirty();render('sections');}
    if(action==='menu-new'){const key='nav.custom'+Date.now();languages.forEach(lang=>state.site.i18n[lang][key]='Новая ссылка');state.site.content[b.dataset.menu].push({labelKey:key,href:'#/shop'});dirty();render('settings');}
    if(action==='menu-delete'){state.site.content[b.dataset.menu].splice(i,1);dirty();render('settings');}
    if(action==='menu-move'&&i>0){const list=state.site.content[b.dataset.menu];[list[i-1],list[i]]=[list[i],list[i-1]];dirty();render('settings');}
