    if(action==='translation-add'){const key='custom.text'+Date.now();languages.forEach(l=>state.site.i18n[l][key]='Новый текст');dirty();render('content');tell('Добавлен ключ '+key+'. Его можно использовать в меню или полном редакторе.');}
    if(action==='order-pay-refresh'){b.disabled=true;try{await request('/api/admin/orders/'+encodeURIComponent(b.dataset.id)+'/payment',{method:'POST',body:{}});state.orders=(await request('/api/admin/orders')).orders||[];await showOrder(b.dataset.id);tell('Статус оплаты обновлён.');}finally{b.disabled=false;}}
